# Written to be accurate and hedged: no product promises, no invented figures. Part 1 (gravitropism) lives in content_knowledge.py.
def _T(head, rows):
    return ("html", '<div class="tablewrap"><table class="packs"><thead><tr>' + "".join(f"<th>{h}</th>" for h in head) + "</tr></thead><tbody>" +
            "".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows) + "</tbody></table></div>")
def _P(*paras): return ("html", "".join(f"<p>{p}</p>" for p in paras))

